   166  bool CodeStreamDecompress::readHeader(grk_header_info* header_info)
   167  {
   168     if(headerError_)
   169            return false;
   170
   171     if(!headerRead_)
   172     {
   173            validation_list_.push_back(std::bind(&CodeStreamDecompress::decompressValidation, this));
   174            if(!exec(validation_list_))
   175            {
   176                   headerError_ = true;
   177                   return false;
   178            }
   179            headerRead_ = true;
   180            procedure_list_.push_back(std::bind(&CodeStreamDecompress::readHeaderProcedure, this));
   181            procedure_list_.push_back(std::bind(&CodeStreamDecompress::copy_default_tcp, this));
   182            if(!exec(procedure_list_))
   183            {
   184                   headerError_ = true;
   185                   return false;
   186            }
   187            if(header_info)
   188                   headerImage_->has_multiple_tiles =
   189                           headerImage_->has_multiple_tiles && !header_info->single_tile_decompress;
   190            auto composite = getCompositeImage();
   250     /* Check if we have read the main header */
   251     if(decompressor->getState() != DECOMPRESS_STATE_TPH_SOT)
   252     {
   253            Logger::logger_.error("Need to read the main header before setting decompress region");
   254            return false;
   255     }
   256
   257     if(region != grk_rect_double(0, 0, 0, 0))
   258     {
   259            grk_rect16 tilesToDecompress;
   260            /* Check if the region provided by the user is correct */
   261            uint32_t start_x = (uint32_t)region.x0 + image->x0;
   262            uint32_t start_y = (uint32_t)region.y0 + image->y0;
   263            uint32_t end_x = (uint32_t)region.x1 + image->x0;
   264            uint32_t end_y = (uint32_t)region.y1 + image->y0;
   265            /* Left */
   266            if(start_x > image->x1)
   267            {
   268                   Logger::logger_.error("Left position of the decompress region (%u)"
   269                                                             " is outside of the image area (Xsiz=%u).",
   270                                                             start_x, image->x1);
   271                   return false;
   272            }
   273            else
   274            {
   275                   tilesToDecompress.x0 = uint16_t((start_x - cp_.tx0) / cp_.t_width);
   276                   compositeImage->x0 = start_x;
   277            }
   278
   279            /* Up */
   280            if(start_y > image->y1)
   281            {
   282                   Logger::logger_.error("Top position of the decompress region (%u)"
   283                                                             " is outside of the image area (Ysiz=%u).",
   284                                                             start_y, image->y1);
   285                   return false;
   286            }
   287            else
   288            {
   289                   tilesToDecompress.y0 = uint16_t((start_y - cp_.ty0) / cp_.t_height);
   290                   compositeImage->y0 = start_y;
   291            }
   292
   293            /* Right */
   294            assert(end_x > 0);
   295            assert(end_y > 0);
   296            if(end_x > image->x1)
   297            {
   298                   Logger::logger_.warn("Right position of the decompress region (%u)"
   299                                                            " is outside the image area (Xsiz=%u).",
   300                                                            end_x, image->x1);
   301                   tilesToDecompress.x1 = cp_.t_grid_width;
   302                   compositeImage->x1 = image->x1;
   303            }
   304            else
   305            {
   306                   // avoid divide by zero
   307                   if(cp_.t_width == 0)
   308                          return false;
   309                   tilesToDecompress.x1 = uint16_t(ceildiv<uint32_t>(end_x - cp_.tx0, cp_.t_width));
   310                   compositeImage->x1 = end_x;
   311            }
   312
   313            /* Bottom */
   314            if(end_y > image->y1)
   315            {
   316                   Logger::logger_.warn("Bottom position of the decompress region (%u)"
   317                                                            " is outside of the image area (Ysiz=%u).",
   318                                                            end_y, image->y1);
   319                   tilesToDecompress.y1 = cp_.t_grid_height;
   320                   compositeImage->y1 = image->y1;
   321            }
   322            else
   323            {
   324                   // avoid divide by zero
   325                   if(cp_.t_height == 0)
   326                          return false;
   327                   tilesToDecompress.y1 = (uint16_t)(ceildiv<uint32_t>(end_y - cp_.ty0, cp_.t_height));
   328                   compositeImage->y1 = end_y;
   329            }
   330            decompressor->tilesToDecompress_.schedule(tilesToDecompress);
   331            cp_.wholeTileDecompress_ = false;
   332            if(!compositeImage->subsampleAndReduce(cp_.coding_params_.dec_.reduce_))
   333                   return false;
   334
   335            Logger::logger_.info("decompress region canvas coordinates set to (%u,%u,%u,%u)",
   336                                                     compositeImage->x0, compositeImage->y0, compositeImage->x1,
   337                                                     compositeImage->y1);
   338            auto scaledX0 = double(compositeImage->x0 - image->x0) / double(image->width());
   339            auto scaledY0 = double(compositeImage->y0 - image->y0) / double(image->height());
   340            auto scaledX1 = double(compositeImage->x1 - image->x0) / double(image->width());

